<template><div class="auth-page"><div class="orb orb-one"></div><div class="orb orb-two"></div><main class="auth-card"><div class="auth-mark"><el-icon :size="30"><UserFilled /></el-icon></div><span class="eyebrow">AIworld</span><h1>创建账号</h1><p>AI 角色世界与多角色互动聊天平台</p><el-form ref="formRef" :model="form" :rules="rules" @submit.prevent="handleRegister"><el-form-item prop="username"><el-input v-model="form.username" placeholder="请设置用户名（3–32 位）" size="large" :prefix-icon="User" clearable /></el-form-item><el-form-item prop="password"><el-input v-model="form.password" :type="showPassword?'text':'password'" placeholder="请设置密码（6–32 位）" size="large" :prefix-icon="Lock"><template #suffix><el-icon class="toggle-icon" role="button" aria-label="切换密码显示" @click="showPassword=!showPassword"><View v-if="!showPassword"/><Hide v-else/></el-icon></template></el-input></el-form-item><el-form-item prop="confirmPassword"><el-input v-model="form.confirmPassword" :type="showConfirmPassword?'text':'password'" placeholder="请再次输入密码" size="large" :prefix-icon="Lock"><template #suffix><el-icon class="toggle-icon" role="button" aria-label="切换确认密码显示" @click="showConfirmPassword=!showConfirmPassword"><View v-if="!showConfirmPassword"/><Hide v-else/></el-icon></template></el-input></el-form-item><el-form-item prop="nickname"><el-input v-model="form.nickname" placeholder="昵称（可选）" size="large" :prefix-icon="UserFilled" clearable /></el-form-item><el-button native-type="submit" type="primary" size="large" class="submit-button" :loading="loading">{{ loading?'注册中…':'注册' }}</el-button></el-form><footer><span>已有账号？</span><RouterLink to="/login">返回登录</RouterLink></footer></main></div></template>
<script setup>
import{reactive,ref}from'vue';import{useRouter}from'vue-router';import{ElMessage}from'element-plus';import{Hide,Lock,User,UserFilled,View}from'@element-plus/icons-vue';import{register as registerApi}from'../api/user'
const router=useRouter(),formRef=ref(null),loading=ref(false),showPassword=ref(false),showConfirmPassword=ref(false);const form=reactive({username:'',password:'',confirmPassword:'',nickname:''});const validateConfirmPassword=(_rule,value,callback)=>value===form.password?callback():callback(new Error('两次输入的密码不一致'));const rules={username:[{required:true,message:'请输入用户名',trigger:'blur'},{min:3,max:32,message:'用户名长度为 3-32 个字符',trigger:'blur'}],password:[{required:true,message:'请输入密码',trigger:'blur'},{min:6,max:32,message:'密码长度为 6-32 个字符',trigger:'blur'}],confirmPassword:[{required:true,message:'请再次输入密码',trigger:'blur'},{validator:validateConfirmPassword,trigger:'blur'}]}
async function handleRegister(){if(!formRef.value||loading.value)return;const valid=await formRef.value.validate().catch(()=>false);if(!valid)return;loading.value=true;try{await registerApi({username:form.username,password:form.password,nickname:form.nickname||undefined});ElMessage.success('注册成功，请登录');await router.push({path:'/login',query:{username:form.username}})}catch{}finally{loading.value=false}}
</script>
<style lang="scss" scoped>
.auth-page{position:relative;min-height:100vh;display:grid;place-items:center;padding:40px 20px;overflow:hidden;color:var(--app-text);background:radial-gradient(circle at 8% 20%,rgba(255,171,135,.34),transparent 28%),radial-gradient(circle at 91% 12%,rgba(131,205,243,.42),transparent 30%),radial-gradient(circle at 72% 92%,rgba(144,231,197,.38),transparent 27%),var(--app-bg-cool)}.orb{position:absolute;border-radius:50%;pointer-events:none}.orb-one{width:180px;height:180px;left:5%;bottom:8%;background:var(--app-lavender-soft)}.orb-two{width:120px;height:120px;right:9%;top:25%;background:var(--app-peach-soft)}.auth-card{position:relative;width:min(460px,100%);padding:36px 40px 29px;text-align:center;border:1px solid var(--app-border);border-radius:var(--app-radius-lg);background:rgba(255,255,255,.95);box-shadow:var(--app-shadow-lg)}.auth-mark{width:60px;height:60px;display:grid;place-items:center;margin:0 auto 14px;border-radius:19px;color:var(--app-primary-strong);background:linear-gradient(145deg,var(--app-mint-soft),var(--app-sky-soft))}.eyebrow{color:var(--app-primary-strong);font-size:11px;font-weight:850;letter-spacing:1.8px}h1{margin:6px 0;font-size:30px;letter-spacing:-.03em}p{margin-bottom:22px;color:var(--app-text-secondary)}.el-form{text-align:left}:deep(.el-form-item){margin-bottom:16px}:deep(.el-input__wrapper){min-height:46px;border-radius:var(--app-radius-sm);background:var(--app-surface-subtle);box-shadow:0 0 0 1px var(--app-border-strong) inset}:deep(.el-input__wrapper.is-focus){box-shadow:0 0 0 1px var(--app-primary) inset,var(--app-focus-ring)}:deep(.el-input__inner){color:var(--app-text)}.toggle-icon{cursor:pointer;color:var(--app-text-muted)}.submit-button{width:100%;min-height:48px;border-radius:var(--app-radius-sm);font-weight:750;--el-button-bg-color:var(--app-primary);--el-button-border-color:var(--app-primary);--el-button-hover-bg-color:var(--app-primary-strong);--el-button-hover-border-color:var(--app-primary-strong)}footer{display:flex;justify-content:center;gap:7px;margin-top:20px;padding-top:17px;border-top:1px solid var(--app-border);color:var(--app-text-secondary)}footer a{color:var(--app-primary-strong);font-weight:750}@media(max-width:500px){.auth-card{padding:30px 22px 24px}}
</style>
